        "code": "import hashlib\nimport hmac\nimport os\n\npassword = \"Tr0ub4dor&3\"\n\n# WEAK: MD5 is fast and unsalted -> same password = same hash, cracked by GPU or rainbow tables\nweak = hashlib.md5(password.encode()).hexdigest()\nprint(\"MD5 (weak)     :\", weak)\n\n# STRONG: a slow key-derivation function with a random salt per user\nsalt = os.urandom(16)\nITERATIONS = 600_000\nstrong = hashlib.pbkdf2_hmac(\"sha256\", password.encode(), salt, ITERATIONS)\nprint(\"PBKDF2 (strong):\", len(strong), \"bytes, salt of\", len(salt), \"bytes\")\n\n\ndef verify(candidate):\n    test = hashlib.pbkdf2_hmac(\"sha256\", candidate.encode(), salt, ITERATIONS)\n    # Constant-time comparison: no timing side channel\n    return hmac.compare_digest(test, strong)\n\n\nprint(\"Right password :\", verify(\"Tr0ub4dor&3\"))\nprint(\"Wrong password :\", verify(\"password123\"))\n",
