        "code": "def severity(score):\n    # Validate input first: never trust a value coming from a scanner report\n    if not 0.0 <= score <= 10.0:\n        raise ValueError(f\"invalid CVSS score: {score}\")\n    if score == 0.0:\n        return \"None\"\n    if score < 4.0:\n        return \"Low\"\n    if score < 7.0:\n        return \"Medium\"\n    if score < 9.0:\n        return \"High\"\n    return \"Critical\"\n\n\nfor value in (0, 3.9, 4.0, 7.5, 9.8, 11):\n    try:\n        print(value, \"->\", severity(value))\n    except ValueError as error:\n        print(value, \"->\", \"rejected:\", error)\n",
