        "code": "import re\nfrom collections import Counter\n\n# Sample lines in the real sshd format (documentation IP ranges)\nLOG = \"\"\"\\\nMar 10 06:25:01 web01 sshd[1201]: Failed password for root from 203.0.113.45 port 51122 ssh2\nMar 10 06:25:03 web01 sshd[1201]: Failed password for root from 203.0.113.45 port 51124 ssh2\nMar 10 06:25:05 web01 sshd[1203]: Failed password for invalid user admin from 203.0.113.45 port 51130 ssh2\nMar 10 06:26:10 web01 sshd[1210]: Accepted publickey for deploy from 198.51.100.23 port 40022 ssh2\nMar 10 06:27:44 web01 sshd[1215]: Failed password for invalid user test from 192.0.2.10 port 33900 ssh2\nMar 10 06:28:02 web01 sshd[1220]: Failed password for root from 203.0.113.45 port 51140 ssh2\n\"\"\"\n\nPATTERN = re.compile(r\"Failed password for (?:invalid user )?(\\S+) from (\\d{1,3}(?:\\.\\d{1,3}){3})\")\nTHRESHOLD = 3  # failures before we call it a brute-force attempt\n\nby_ip = Counter()\nusers = Counter()\nfor line in LOG.splitlines():\n    match = PATTERN.search(line)\n    if match:\n        users[match.group(1)] += 1\n        by_ip[match.group(2)] += 1\n\nfor ip, count in by_ip.most_common():\n    flag = \"BRUTE FORCE\" if count >= THRESHOLD else \"ok\"\n    print(f\"{ip:<15} {count} failures  {flag}\")\nprint(\"Most targeted account:\", users.most_common(1)[0][0])\n",
