        "code": "import ipaddress\n\nSENSITIVE_PORTS = {22, 3389, 3306, 5432}  # SSH, RDP, MySQL, PostgreSQL\n\n\ndef audit_rule(port, source):\n    network = ipaddress.ip_network(source)  # raises ValueError on an invalid CIDR\n    open_to_world = network.prefixlen == 0\n    if open_to_world and port in SENSITIVE_PORTS:\n        return \"CRITICAL\"\n    # A wide public range is suspicious even on a web port\n    if not network.is_private and network.num_addresses > 256:\n        return \"WARNING\"\n    return \"OK\"\n\n\nrules = [(22, \"0.0.0.0/0\"), (443, \"0.0.0.0/0\"), (22, \"10.0.0.0/8\"), (5432, \"203.0.113.10/32\")]\nfor port, source in rules:\n    print(f\"{port:<5} {source:<18} {audit_rule(port, source)}\")\n",
